import path from 'node:path'
import { defineConfig } from '@alova/wormhole'
import type { GeneratorConfig } from '@alova/wormhole'
import { stripOperationIdPrefix, stripTagPrefix, stripSchemaPrefix, requiredResponses, modelDefaults, exposeApis } from './codegen/plugins'
import { emitApi, emitIndex } from './codegen/emitApi'

// Swagger source: docs/swagger.json (generated by ./main.sh docs at repo root).
// wormhole transpiles this config to a temporary CJS module inside this package,
// so `__dirname` is the package directory regardless of the caller's cwd. The
// cwd fallback covers a plain ESM load.
const here = typeof __dirname === 'string' ? __dirname : process.cwd()
const input = path.resolve(here, '../../../docs/swagger.json')

// Generated artifacts land in the shared `@sdk/client` package, not in an app:
// both apps consume the same file layout (`api.ts` facade + wormhole types) and
// differ only in which endpoints they get. The runtime (`src/runtime.ts`,
// `src/createApis.ts`) is hand-written there and injected by each app's plugin.
const sdkDir = (app: string) => path.resolve(here, `../sdk/src/${app}`)

const includePaths = (prefixes: string[]) => (api: unknown) => {
  if (!api || typeof api !== 'object') return undefined
  const { url, path: route } = api as { url?: unknown; path?: unknown }
  const target = typeof url === 'string' ? url : typeof route === 'string' ? route : ''
  return prefixes.some((p) => target.startsWith(p)) ? api : undefined
}

/**
 * One generator per app. Plugin order is execution order: the rename plugins
 * reshape the document first, then everything that emits code reads it.
 */
const generator = (app: 'usr' | 'adm', prefixes: string[], global: string): GeneratorConfig => {
  const out = sdkDir(app)
  return {
    input,
    output: out,
    type: 'ts',
    global,
    handleApi: includePaths(prefixes),
    plugins: [
      stripOperationIdPrefix(app),
      stripTagPrefix(app),
      // restore clean model names (UsrAuth -> Auth, ...); global shared models
      // like BaseQueries / db.User stay unprefixed and untouched.
      stripSchemaPrefix(app === 'usr' ? 'Usr' : 'Adm'),
      requiredResponses(prefixes),
      // `declare global { interface UsrApis }` -> `export interface Apis`
      exposeApis(global),
      modelDefaults(out, prefixes),
      emitApi(out, prefixes),
      emitIndex(out),
    ],
  }
}

export default defineConfig({
  generator: [
    // ── User app: usr + public (std) ───────────────────────────────────
    generator('usr', ['/usr/api/v1', '/api/v1'], 'UsrApis'),
    // ── Admin app: adm + public (std) ──────────────────────────────────
    generator('adm', ['/adm/api/v1', '/api/v1'], 'AdmApis'),
  ],
})
